24	/// Execute a query command.
25	pub fn query(command: &'static QueryCommand) -> HintedStrResult<()> {
26	    let mut world =
27	        SystemWorld::new(Some(&command.input), &command.world, &command.process)?;
28	
29	    // Reset everything and ensure that the main file is present.
30	    world.reset();
31	    world.source(world.main()).map_err(|err| err.to_string())?;
32	
33	    let Warned { output, mut warnings } = match command.target {
34	        Target::Paged => typst::compile::<PagedDocument>(&world)
35	            .map(|result| result.map(|output| Box::new(output) as Box<dyn Output>)),
36	        Target::Html => typst::compile::<HtmlDocument>(&world)
37	            .map(|result| result.map(|output| Box::new(output) as Box<dyn Output>)),
38	        Target::Bundle => typst::compile::<Bundle>(&world)
39	            .map(|result| result.map(|output| Box::new(output) as Box<dyn Output>)),
40	    };
41	
42	    // Add deprecation warning.
43	    warnings.push(deprecation_warning(command));
44	
45	    match output {
46	        // Retrieve and print query results.
47	        Ok(output) => {
48	            let data = retrieve(&world, command, output.introspector())?;
49	            let serialized = format(data, command)?;
